const atlasEsc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function atlasCard(id){const e=ATLAS.find(e=>e.id===id);if(!e)return '';return `<article class="entry atlas-card"><a href="#entry/${e.id}" class="atlas-visual ${e.category==='人物'?'person':''}"><img loading="lazy" src="${e.image}" alt="${atlasEsc(e.name)} · 艺术演绎"></a><small class="eyebrow">${atlasEsc(e.category)}</small><h3><a href="#entry/${e.id}">${atlasEsc(e.name)}</a></h3><p>${atlasEsc(e.intro)}</p><a class="scribble" href="#entry/${e.id}">展开档案、引文与关联章节 ↗</a></article>`}function atlasPage(id){const e=ATLAS.find(e=>e.id===id);if(!e)return '<section class="wrap"><h2>未找到这个条目</h2><a href="#archive">返回档案</a></section>';const src=e.source;const mapQueries={'A019':'Sandycove Martello Tower Dublin','A020':'Dalkey Ireland','A021':'Sandymount Strand Dublin','A022':'7 Eccles Street Dublin','A024':'Westland Row Dublin','A025':'Saint Andrews Church Westland Row Dublin','A026':'Swenys Dublin','A029':'Glasnevin Cemetery Dublin','A031':'OConnell Street Dublin','A033':'OConnell Bridge Dublin','A036':'National Library of Ireland Dublin','A037':'River Liffey Dublin','A041':'Holles Street Dublin','A046':'Butt Bridge Dublin','A047':'Howth Head Dublin','A048':'Gibraltar','A049':'James Joyce Centre Dublin'};const namedPlaces=['A019','A020','A021','A022','A024','A025','A026','A029','A031','A033','A036','A037','A041','A046','A047','A048','A049'];const placeLink=namedPlaces.includes(e.id)?`<a class="button" href="https://www.openstreetmap.org/search?query=${encodeURIComponent(mapQueries[e.id]||e.name)}" target="_blank" rel="noopener">查找今日相关地名 ↗</a><p class="muted">地名搜索不等于原址认证。回忆、预想、拆除建筑与今日地点须按本条说明区分。</p>`:'';return `<section class="wrap"><a class="back" href="#archive">← 都柏林档案</a><p class="eyebrow">${atlasEsc(e.category)} / ${e.id}</p><h2>${atlasEsc(e.name)}</h2><div class="atlas-detail"><div><a href="${e.image}" target="_blank" rel="noopener"><img class="atlas-full" src="${e.image}" alt="${atlasEsc(e.name)} · 点击查看完整画幅"></a><p class="muted">AI艺术演绎；不作历史照片、肖像鉴定或建筑复原证据。点击查看完整画幅。</p></div><div><span class="stamp">${atlasEsc(e.state)}</span><p class="atlas-intro">${atlasEsc(e.intro)}</p>${placeLink}${e.external?`<a class="scribble" href="${atlasEsc(e.external)}" target="_blank" rel="noopener">相关机构资料 ↗</a>`:''}<h3>回到书里</h3><div class="tools">${e.chapters.map(n=>`<a class="button" href="#chapter/${n}">第${n}章</a>`).join('')}</div><h3>相关片段与出处</h3>${src?`<small>${atlasEsc(src.type)} · 检索词“${atlasEsc(src.keyword)}”</small><blockquote class="atlas-quote">${atlasEsc(src.text)}</blockquote><span>核对原PDF第${src.page}页 ↗（原PDF未随项目提供）</span>`:`<p>当前依据：${atlasEsc(e.pdfBasis)}。本条尚无精确匹配的页内摘引；可从关联章节继续核对，不以自动生成文字冒充原文。</p>`}<details class="notice"><summary>资料范围与核验说明</summary><p>${atlasEsc(e.verification)}</p>${e.editorNotes?`<p>${atlasEsc(e.editorNotes)}</p>`:""}<p>人物简介是编辑整理。译本附录中的评价与正文人物的偏见不自动成为本站的中立定义。</p></details></div></div></section>`}function atlasGalleryHTML(){return `<section class="wrap"><span class="eyebrow">117 SUBJECTS / 图像手札</span><h2>把图像，放回各自的故事。</h2><p class="muted">按主题逐项制作，章节、地点、人物、群体与物件可分别检索。所有图像为艺术演绎。</p><div class="tools"><input id="atlas-gallery-search" aria-label="搜索图像" placeholder="搜索图像主题"><select id="atlas-gallery-type" aria-label="图像类型"><option value="">全部类型</option>${[...new Set(ATLAS.map(e=>e.category))].map(c=>`<option>${atlasEsc(c)}</option>`).join('')}</select></div><div id="atlas-gallery-results" class="gallery">${ATLAS.map(atlasFigure).join('')}</div></section>`}function atlasFigure(e){return `<figure><a href="${e.image}" target="_blank" rel="noopener"><img loading="lazy" src="${e.image}" alt="${atlasEsc(e.name)} · 完整画幅"></a><figcaption>${atlasEsc(e.name)}<br><a class="scribble" href="#entry/${e.id}">查看档案与出处 ↗</a></figcaption></figure>`}function filterAtlasGallery(){const q=document.querySelector('#atlas-gallery-search')?.value||'',cat=document.querySelector('#atlas-gallery-type')?.value||'';const box=document.querySelector('#atlas-gallery-results');if(box)box.innerHTML=ATLAS.filter(e=>(!q||(e.name+e.intro).includes(q))&&(!cat||e.category===cat)).map(atlasFigure).join('')||'<p>没有匹配图像，请换个关键词。</p>'}document.addEventListener('input',e=>{if(e.target.id==='atlas-gallery-search')filterAtlasGallery()});document.addEventListener('change',e=>{if(e.target.id==='atlas-gallery-type')filterAtlasGallery()});
function renderAtlasReading(c){let art=ATLAS.filter(e=>e.category==='随文小插图／物件'&&e.chapters.includes(+c.章号)).slice(0,2);if(!art.length)art=ATLAS.filter(e=>e.category==='地点／空间'&&e.chapters.includes(+c.章号)).slice(0,1);const lines=c.body.split('\n'),inserts=new Map();for(let k=0;k<art.length;k++){const e=art[k],word=e.name.split(/[与／/]/)[0];let at=lines.findIndex(l=>l.includes(word));if(at<0)at=Math.floor(lines.length*(k+1)/(art.length+1));while(at<lines.length-1&&!/[。！？]$/.test(lines[at].trim()))at++;const fig=`<figure class="inline-illustration"><a href="${e.image}" target="_blank" rel="noopener"><img width="480" height="290" loading="lazy" src="${e.image}" alt="${atlasEsc(e.name)} · 编辑配图"></a><figcaption>编辑配图 · 艺术演绎<br><a href="#entry/${e.id}">${atlasEsc(e.name)} · 查看档案 ↗</a></figcaption></figure>`;inserts.set(at,(inserts.get(at)||'')+fig)}return lines.map((l,i)=>atlasEsc(l)+(inserts.get(i)||'')).join('\n')}
